class Rejected(ValueError):pass


def decode(request,catalog,bindings):
    if not isinstance(request,dict) or set(request)!={'operation_id','class_id','target_id','expected_precondition'} or any(type(v)is not str for v in request.values()):raise Rejected('Exact typed schema required')
    cap=next((c for c in catalog if c['FIXED_OPERATION']==request['operation_id']),None)
    if cap is None:raise Rejected('Unknown operation enum')
    if (request['class_id'],request['target_id']) not in bindings[cap['CAPABILITY_ID']]:raise Rejected('Class/target pair not authorized')
    if request['expected_precondition']!=digest(cap):raise Rejected('Wrong frozen contract identity')
    return cap['CAPABILITY_ID']


